// #8a7f1a (99af04b9faa9d626508a7f1a) «iOS - מסך «תפילות»: כשהמקלדת פתוחה, לחיצה ראשונה על «ניקוי החיפוש» רק סוגרת את המקלדת ולא מנקה
// את החיפוש» — עבר QA 25.10.2026 (iPhone 17, TestFlight 1.0.0 (20) + OTA после commit c6f2fea).
// מה רצוי: «המשתמש לוחץ פעם אחת על «ניקוי החיפוש» (גם כשהמקלדת פתוחה) → החיפוש מתנקה, המקלדת נסגרת ורשימת כל התפילות חוזרת»
// (опора F-40 AC4 / S-27 AC3; «одно нажатие» — из тикета, AC про клавиатуру нет).
// Факт 25.10: 3/3 — одно нажатие при открытой клавиатуре: поле пустое, клавиатура закрыта, список вернулся (8a7f1a-before/after1.png).
// Клавиатуру перед нажатием НЕ скрываем (в этом смысл теста). Кейс: .qa/tests/prayer-catalog/PC-07-clear-search-keyboard-open.md.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains } from '../../helpers/ui.ts';
import { shown } from '../_lib/app-0710.ts';
import { goHome, openCatalog, catalogSearch, button } from '../_lib/readiness-1910.ts';
import { fieldValue } from '../_lib/app-1410.ts';
import { catalogTitles, EMPTY_SEARCH, CLEAR_SEARCH, LESSONS_CARD } from '../_lib/app-2110.ts';
import { saveShot, typeKeepKeyboard, keyboardShown } from '../_lib/app-2510.ts';

const RUNS = 3;

describe('25.10 — «ניקוי החיפוש» при открытой клавиатуре (#8a7f1a)', () => {
  afterEach(async () => {
    if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
    const b = await button(CLEAR_SEARCH);
    if (await b.isExisting().catch(() => false)) await b.click().catch(() => {});
    await goHome().catch(() => {});
  });

  it('PC-07 «תפילות»: «זזזזז» с открытой клавиатурой → ОДНО нажатие «ניקוי החיפוש»: поле пустое, клавиатура закрыта, весь список (×3) #8a7f1a #99af04b9 F-40 AC4 S-27 AC3 @prod-safe', async function () {
    this.timeout(600000);
    await openCatalog();
    const full = await catalogTitles();
    console.log(`[PC-07] полный список: ${full.join(' | ')}`);
    expect(full).toContain(LESSONS_CARD);
    for (let i = 1; i <= RUNS; i++) {
      const f = (await catalogSearch()) as unknown as WebdriverIO.Element;
      await typeKeepKeyboard(f, 'זזזזז');
      await expect(byTextContains(EMPTY_SEARCH)).toBeExisting({ wait: 15000 });
      expect(await keyboardShown()).toBe(true);                   // клавиатура открыта в момент нажатия
      if (i === 1) await saveShot('PC-07-before.png');
      await (await button(CLEAR_SEARCH)).click();                  // одно нажатие
      await driver.waitUntil(async () => (await fieldValue(f)).replace('חיפוש', '').trim() === '',
        { timeout: 5000, timeoutMsg: `попытка ${i}: после одного нажатия поле не очистилось` });
      expect(await keyboardShown()).toBe(false);
      expect(await shown(byTextContains(EMPTY_SEARCH))).toBe(false);
      await expect(byText(CLEAR_SEARCH)).not.toBeExisting();
      await driver.waitUntil(async () => (await catalogTitles()).length >= full.length,
        { timeout: 5000, timeoutMsg: `попытка ${i}: полный список не вернулся` });
      expect(await catalogTitles()).toEqual(full);
    }
    await saveShot('PC-07-after.png');
  });
});
